// Match the dust tile's RGB before changing alpha so unrelated textures are
// left alone. Other particle tiles vary in RGB across battles but have the
// same captured alpha mask, so the known game sheet uses that complete mask.
// Synthetic or unfamiliar signatures retain the narrow dust-tile repair.
static inline bool mtw_dust_atlas_alpha_sentinels_bad(
    const uint16_t *pixels, unsigned pitch_bytes) {
    if (!pixels || pitch_bytes < 256u * sizeof(uint16_t) ||
        pitch_bytes % sizeof(uint16_t))
        return false;
    const unsigned pitch_words = pitch_bytes / sizeof(uint16_t);
    // These transparent pixels span the dust tile and other particle tiles.
    const unsigned samples[] = {0u, 127u, 32000u, 65533u};
    for (unsigned offset : samples) {
        const uint16_t pixel =
            pixels[(offset / 256u) * pitch_words + (offset % 256u)];
        if (pixel & 0x8000u) return true;
    }
    return false;
}

static inline unsigned mtw_repair_dust_atlas_alpha(
    uint16_t *pixels, unsigned pitch_bytes, uint64_t expected_rgb_hash,
    unsigned expected_black_pixels) {
    if (!pixels || pitch_bytes < 256u * sizeof(uint16_t) ||
        pitch_bytes % sizeof(uint16_t) || expected_black_pixels > 128u * 128u)
        return 0u;
    const unsigned pitch_words = pitch_bytes / sizeof(uint16_t);
    uint64_t hash = UINT64_C(14695981039346656037);
    unsigned black_pixels = 0u;
    for (unsigned y = 0u; y < 128u; ++y) {
        const uint16_t *row = pixels + y * pitch_words;
        for (unsigned x = 0u; x < 128u; ++x) {
            const uint16_t rgb = row[x] & 0x7fffu;
            hash = (hash ^ rgb) * UINT64_C(1099511628211);
            black_pixels += rgb == 0u;
        }
    }
    if (hash != expected_rgb_hash || black_pixels != expected_black_pixels)
        return 0u;

    const bool full_sheet =
        expected_rgb_hash == UINT64_C(0x389100512363FEBD) &&
        expected_black_pixels == 6847u;

    unsigned changed = 0u;
    unsigned transparent_run = 0u;
    const unsigned transparent_run_count =
        sizeof(k_mtw_particle_transparent_runs) /
        sizeof(k_mtw_particle_transparent_runs[0]);
    for (unsigned y = 0u; y < (full_sheet ? 256u : 128u); ++y) {
        uint16_t *row = pixels + y * pitch_words;
        for (unsigned x = 0u; x < (full_sheet ? 256u : 128u); ++x) {
            const uint16_t rgb = row[x] & 0x7fffu;
            bool opaque = rgb != 0u;
            if (full_sheet) {
                const unsigned offset = y * 256u + x;
                while (transparent_run < transparent_run_count &&
                       k_mtw_particle_transparent_runs[transparent_run][1] < offset)
                    ++transparent_run;
                opaque = transparent_run == transparent_run_count ||
                    k_mtw_particle_transparent_runs[transparent_run][0] > offset;
            }
            const uint16_t repaired = rgb | (opaque ? 0x8000u : 0u);
            changed += row[x] != repaired;
            row[x] = repaired;
        }
    }
    return changed;
}

